def smallestDivisor(nums, threshold):
    lo, hi = 1, max(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        cost = 0
        for x in nums:
            cost += (x + mid - 1) // mid
        if cost <= threshold:
            hi = mid
        else:
            lo = mid + 1
    return lo
